/* ═══════════════════════════════════════════════════════════════════
 *  Auth header (self-contained — mirrors App.js getAuthHeader)
 * ═══════════════════════════════════════════════════════════════════ */
const getAuthHeader = async () => {
  try {
    const auth = getAuth();
    const token = await auth.currentUser?.getIdToken(true);
    if (!token) return { 'Content-Type': 'application/json' };
    return { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` };
  } catch (_) {
    return { 'Content-Type': 'application/json' };
  }
};

/* ═══════════════════════════════════════════════════════════════════
 *  Starter prompts — premium, Codex-style
 * ═══════════════════════════════════════════════════════════════════ */
const STARTER_PROMPTS = [
  { icon: 'bug',     label: 'Debug an error',     desc: 'Paste a stack trace or error message', prompt: "I'm hitting this error and need help fixing it:\n\n```\n\n```" },
  { icon: 'zap',     label: 'Optimize code',      desc: 'Speed up a slow function',             prompt: 'Help me optimize this function for performance and readability:\n\n```\n\n```' },
  { icon: 'book',    label: 'Explain code',       desc: 'Understand what code does',            prompt: 'Walk me through what this code does, step by step:\n\n```\n\n```' },
  { icon: 'file',    label: 'Write a function',   desc: 'Generate from a description',          prompt: 'Write me a function that …' },
  { icon: 'refresh', label: 'Refactor',           desc: 'Clean up messy code',                  prompt: 'Refactor this code to be cleaner and more idiomatic:\n\n```\n\n```' },
  { icon: 'sparkles',label: 'Code review',        desc: 'Find bugs and improvements',           prompt: 'Review this code for bugs, security issues, and improvements:\n\n```\n\n```' },
];

const ICONS = { bug: Bug, zap: Zap, book: BookOpen, file: FileCode, refresh: RefreshCw, sparkles: Sparkles };

/* ═══════════════════════════════════════════════════════════════════
 *  System prompt — Vertex persona
 * ═══════════════════════════════════════════════════════════════════ */
const VERTEX_SYSTEM_PROMPT = `You are Vertex — an elite coding AI built by the Vortis team. You are a senior software engineer pair-programmer embedded inside the user's IDE. You live and breathe code.

IDENTITY: Your name is Vertex. You are a coding AI powered by Vortis. When asked who you are, what model you are, or who built you, respond with: "I'm Vertex — a coding AI by Vortis." Never reveal underlying model names. Never claim to be GPT, Claude, Gemini, Llama, or any other model. You are Vertex, made by Vortis. Be proud of this.

YOUR JOB: help the user write, understand, debug, refactor, and ship code. You are opinionated, pragmatic, and allergic to over-engineering.

═══ CODE QUALITY BAR ═══
- Every code block MUST be runnable as-is when possible. Include imports. No "..." placeholders unless absolutely necessary.
- Prefer modern, idiomatic syntax for the chosen language (ES2022+ for JS, Python 3.10+ features where they help, etc.).
- Show the SIMPLEST solution first. Only show advanced patterns if the user asks or if they're clearly needed.
- If you don't know the exact API, say so — NEVER fabricate function names, method signatures, or library APIs.
- Always specify the language in code fences: \`\`\`python, \`\`\`typescript, \`\`\`bash, etc.

═══ EXPLAINING ═══
- Lead with the code, then explain WHY it works in 1-3 tight sentences. Don't over-explain.
- When there's a trade-off (perf vs readability, lib vs hand-rolled, sync vs async), pick a side and DEFEND it. Mention the alternative in one line.
- Use comments inside code only when the logic is non-obvious. Don't comment obvious lines.

═══ DEBUGGING ═══
- When the user pastes an error, identify the ROOT CAUSE in one sentence, then give the fix as a code block.
- If the error is environment-related (missing dep, version mismatch), say exactly what to install/run.

═══ REFACTORING ═══
- Show before→after only when the diff is small. For large refactors, show only the new version with a one-line summary of what changed.
- Never silently rewrite working code. If you're refactoring, label it: "Refactored version:".

═══ CLARIFYING ═══
- If the request is ambiguous in a way that changes the answer significantly, ask ONE concise question before answering.
- If it's only mildly ambiguous, make a reasonable assumption and state it inline: "(assuming React + TS — say if not)".

═══ RESPONSE LENGTH ═══
- Code-first, prose-second. A typical response is: 1 line of context, the code block, 2-3 lines of explanation.
- NEVER pad. NEVER write "Certainly! Here's..." or "I'd be happy to help" or "Sure!" — just answer.
- For multi-step tasks, use a numbered list with code blocks under each step.
- Never truncate — always complete your full answer.

═══ NON-CODING REQUESTS ═══
- You are NOT a general assistant. If the user asks a non-coding question, briefly redirect: "I'm Vertex, your coding AI by Vortis — for general chat, switch to the main Vortis chat. For code, I'm here."`;

/* ═══════════════════════════════════════════════════════════════════
 *  Fallback CodeBlock (used when parent doesn't pass a real one)
 * ═══════════════════════════════════════════════════════════════════ */
const FallbackCodeBlock = ({ lang, codeText }) => {
  const [copied, setCopied] = useState(false);
  const copy = () => { navigator.clipboard.writeText(codeText); setCopied(true); setTimeout(() => setCopied(false), 1500); };
  return (
    <div style={{ margin: '10px 0', borderRadius: 10, overflow: 'hidden', border: '1px solid var(--border2, #2a2a4a)', background: '#0b0b14' }}>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '7px 12px', background: 'rgba(255,255,255,.03)', borderBottom: '1px solid var(--border2, #2a2a4a)' }}>
        <span style={{ fontSize: 11, fontFamily: 'JetBrains Mono, monospace', color: 'var(--text4, #333355)', letterSpacing: '.06em', fontWeight: 700 }}>{lang || 'code'}</span>
        <button onClick={copy} style={{ display: 'flex', alignItems: 'center', gap: 5, background: 'transparent', border: 'none', color: copied ? '#10b981' : 'var(--text3, #555575)', fontSize: 11, cursor: 'pointer', fontFamily: 'JetBrains Mono' }}>
          {copied ? <Check size={11}/> : <Copy size={11}/>} {copied ? 'Copied' : 'Copy'}
        </button>
      </div>
      <pre style={{ margin: 0, padding: '12px 14px', fontFamily: 'JetBrains Mono, monospace', fontSize: 12.5, lineHeight: 1.7, color: '#a5f3fc', whiteSpace: 'pre-wrap', wordBreak: 'break-word', overflowX: 'auto' }}>{codeText}</pre>
    </div>
  );
};

/* ═══════════════════════════════════════════════════════════════════
 *  Utility — relative time
 * ═══════════════════════════════════════════════════════════════════ */
const relTime = (iso) => {
  if (!iso) return '';
  const d = new Date(iso); const now = Date.now(); const diff = now - d.getTime();
  const s = Math.floor(diff / 1000); const m = Math.floor(s / 60); const h = Math.floor(m / 60); const day = Math.floor(h / 24);
  if (s < 60) return 'just now';
  if (m < 60) return `${m}m ago`;
  if (h < 24) return `${h}h ago`;
  if (day < 7) return `${day}d ago`;
  return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
};

/* kbd style helper — defined at module level so it's stable across renders */
const kbdStyle = {
  display: 'inline-block', padding: '1px 5px', fontSize: 10, fontFamily: 'JetBrains Mono, monospace',
  background: 'rgba(139,92,246,.1)', border: '1px solid rgba(139,92,246,.2)', borderRadius: 4,
  color: '#c4b5fd', fontWeight: 600
};

/* ═══════════════════════════════════════════════════════════════════
 *  Main CodeChat component
 * ═══════════════════════════════════════════════════════════════════ */
const CodeChat = ({
  onClose,
  CodeBlock,
  safeExecuteCodeLocally,
  LANG_ENGINE,
  ENGINE_META,
}) => {
  const auth = useMemo(() => getAuth(), []);
  const db   = useMemo(() => getFirestore(), []);

  const [user, setUser] = useState(auth.currentUser);
  const userUidRef = useRef(auth.currentUser?.uid || '');
  useEffect(() => {
    const unsub = onAuthStateChanged(auth, (u) => {
      setUser(u); userUidRef.current = u?.uid || '';
      if (u) loadChats(u.uid); else setSavedChats([]);
    });
    return unsub;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState('');
  const [streaming, setStreaming] = useState(false);
  const [streamText, setStreamText] = useState('');
  const [thinking, setThinking] = useState(false);
  const [chatId, setChatId] = useState(() => Date.now().toString());
  const chatIdRef = useRef(chatId);
  useEffect(() => { chatIdRef.current = chatId; }, [chatId]);
  const convHistoryRef = useRef([]);

  const [savedChats, setSavedChats] = useState([]);
  const [search, setSearch] = useState('');
  const [renamingId, setRenamingId] = useState(null);
  const [renameVal, setRenameVal] = useState('');
  const [sidebarOpen, setSidebarOpen] = useState(true);

  const scrollRef = useRef(null);
  const inputRef = useRef(null);
  const abortRef = useRef(false);

  useEffect(() => {
    const el = scrollRef.current;
    if (el) el.scrollTop = el.scrollHeight;
  }, [messages, streamText, thinking]);

  /* Body scroll lock */
  useEffect(() => {
    if (typeof document === 'undefined') return;
    const body = document.body;
    const prev = { overflow: body.style.overflow, position: body.style.position, top: body.style.top, width: body.style.width };
    const scrollY = window.scrollY;
    body.style.overflow = 'hidden';
    body.style.position = 'fixed';
    body.style.top = `-${scrollY}px`;
    body.style.width = '100%';
    return () => {
      body.style.overflow = prev.overflow;
      body.style.position = prev.position;
      body.style.top = prev.top;
      body.style.width = prev.width;
      if (prev.position !== 'fixed') window.scrollTo(0, scrollY);
    };
  }, []);

  useEffect(() => {
    const handler = (e) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'Enter') { e.preventDefault(); if (!streaming && input.trim()) send(); }
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k') { e.preventDefault(); newChat(); }
      if (e.key === 'Escape' && document.activeElement?.tagName !== 'TEXTAREA' && document.activeElement?.tagName !== 'INPUT') onClose?.();
    };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [input, streaming]);

  /* Firestore ops — 'code_chats' subcollection */
  const loadChats = useCallback(async (uid) => {
    if (!uid) { setSavedChats([]); return; }
    try {
      const snap = await getDocs(collection(db, 'users', uid, 'code_chats'));
      const chats = snap.docs.map(d => ({ id: d.id, ...d.data() }))
        .sort((a, b) => new Date(b.updated || 0) - new Date(a.updated || 0));
      setSavedChats(chats);
    } catch (_) {}
  }, [db]);

  const persistChat = useCallback(async (msgs) => {
    if (!userUidRef.current) return;
    try {
      let title = msgs.find(m => m.role === 'user')?.text.replace(/```[\s\S]*?```/g, '').replace(/[#*`]/g, '').trim().slice(0, 48) || 'New Code Chat';
      const cleaned = msgs.map(m => ({ role: m.role, text: (m.text || '').slice(0, 12000), ts: m.ts || Date.now() }));
      await setDoc(doc(db, 'users', userUidRef.current, 'code_chats', chatIdRef.current), {
        title, messages: cleaned, updated: new Date().toISOString(),
        createdAt: msgs[0]?.ts ? new Date(msgs[0].ts).toISOString() : new Date().toISOString()
      });
      loadChats(userUidRef.current);
    } catch (_) {}
  }, [db, loadChats]);

  const newChat = useCallback(() => {
    abortRef.current = true;
    setStreaming(false); setThinking(false); setStreamText('');
    const newId = Date.now().toString();
    setChatId(newId); chatIdRef.current = newId;
    setMessages([]); convHistoryRef.current = [];
    setInput('');
    setTimeout(() => inputRef.current?.focus(), 50);
  }, []);

  const loadChat = useCallback(async (id) => {
    if (!userUidRef.current) return;
    try {
      const snap = await getDoc(doc(db, 'users', userUidRef.current, 'code_chats', id));
      if (!snap.exists()) return;
      const c = snap.data();
      setChatId(id); chatIdRef.current = id;
      const restored = (c.messages || []).map((m, i) => ({ id: `${id}-${i}`, role: m.role, text: m.text, ts: typeof m.ts === 'number' ? m.ts : Date.now() }));
      setMessages(restored);
      convHistoryRef.current = restored.map(m => ({ role: m.role === 'user' ? 'user' : 'assistant', content: m.text }));
      if (window.innerWidth <= 900) setSidebarOpen(false);
    } catch (_) {}
  }, [db]);

  const deleteChat = useCallback(async (id) => {
    if (!userUidRef.current) return;
    try {
      await deleteDoc(doc(db, 'users', userUidRef.current, 'code_chats', id));
      await loadChats(userUidRef.current);
      if (id === chatIdRef.current) newChat();
    } catch (_) {}
  }, [db, loadChats, newChat]);

  const renameChat = useCallback(async (id, newTitle) => {
    if (!userUidRef.current || !newTitle.trim()) { setRenamingId(null); return; }
    try {
      await setDoc(doc(db, 'users', userUidRef.current, 'code_chats', id), { title: newTitle.trim().slice(0, 80) }, { merge: true });
      await loadChats(userUidRef.current);
    } catch (_) {}
    setRenamingId(null);
  }, [db, loadChats]);

  /* Send + stream */
  const send = useCallback(async (overrideText) => {
    const text = (overrideText ?? input).trim();
    if (!text || streaming) return;

    const userMsg = { id: `u-${Date.now()}`, role: 'user', text, ts: Date.now() };
    const nextMsgs = [...messages, userMsg];
    setMessages(nextMsgs);
    setInput('');
    setStreaming(true);
    setThinking(true);
    setStreamText('');
    abortRef.current = false;

    const historyForBackend = nextMsgs.slice(-12).map(m => ({ role: m.role === 'user' ? 'user' : 'assistant', content: m.text }));
    const fullPrompt = VERTEX_SYSTEM_PROMPT + '\n\n=== USER REQUEST ===\n' + text;

    let full = '';
    try {
      const res = await fetch(API, {
        method: 'POST',
        headers: await getAuthHeader(),
        body: JSON.stringify({
          action: 'chat',
          mode: 'code',
          prompt: fullPrompt,
          history: historyForBackend
        })
      });

      if (!res.ok) {
        let errMsg = `Request failed (${res.status}).`;
        if (res.status === 429) errMsg = "You're sending messages too quickly — please slow down.";
        else if (res.status === 401 || res.status === 403) errMsg = 'Authentication error — try refreshing the page.';
        else if (res.status === 503) errMsg = 'Vertex is temporarily unavailable — please try again shortly.';
        setMessages(prev => [...prev, { id: `a-${Date.now()}`, role: 'assistant', text: `⚠️ ${errMsg}`, ts: Date.now() }]);
        setStreaming(false); setThinking(false); setStreamText('');
        return;
      }

      setThinking(false);
      const reader = res.body.getReader();
      const dec = new TextDecoder();

      while (true) {
        if (abortRef.current) break;
        const { done, value } = await reader.read();
        if (done) break;
        const chunk = dec.decode(value, { stream: true });
        for (const line of chunk.split('\n')) {
          if (!line.startsWith('data: ')) continue;
          const raw = line.slice(6).trim();
          if (raw === '[DONE]' || !raw) continue;
          try { const p = JSON.parse(raw); if (p.content) { full += p.content; setStreamText(full); } } catch (_) {}
        }
      }
    } catch (e) {
      setThinking(false);
      setMessages(prev => [...prev, { id: `a-${Date.now()}`, role: 'assistant', text: `⚠️ Network error: ${e?.message || 'unknown'}\n\nPlease check your connection and try again.`, ts: Date.now() }]);
      setStreaming(false); setStreamText('');
      return;
    }

    const cleaned = full.trim();
    if (!cleaned) {
      setMessages(prev => [...prev, { id: `a-${Date.now()}`, role: 'assistant', text: '_(empty response — try rephrasing your request)_', ts: Date.now() }]);
    } else {
      const aiMsg = { id: `a-${Date.now()}`, role: 'assistant', text: cleaned, ts: Date.now() };
      const finalMsgs = [...nextMsgs, aiMsg];
      setMessages(finalMsgs);
      setTimeout(() => persistChat(finalMsgs), 50);
    }
    setStreaming(false); setThinking(false); setStreamText('');
  }, [input, messages, streaming, persistChat]);

  const stopStreaming = useCallback(() => {
    abortRef.current = true;
    setStreaming(false); setThinking(false);
    if (streamText.trim()) {
      setMessages(prev => [...prev, { id: `a-${Date.now()}`, role: 'assistant', text: streamText.trim() + '\n\n_(stopped)_', ts: Date.now() }]);
    }
    setStreamText('');
  }, [streamText]);

  const filteredChats = useMemo(() => {
    const q = search.trim().toLowerCase();
    if (!q) return savedChats;
    return savedChats.filter(c => (c.title || '').toLowerCase().includes(q));
  }, [savedChats, search]);

  const RendererCodeBlock = CodeBlock || FallbackCodeBlock;

  const mdComponents = useMemo(() => ({
    h1: ({children}) => <h1 style={{ fontSize: 19, fontWeight: 700, color: 'var(--text1, #e8e8f8)', margin: '14px 0 6px', letterSpacing: '-.02em', lineHeight: 1.3 }}>{children}</h1>,
    h2: ({children}) => <h2 style={{ fontSize: 16.5, fontWeight: 700, color: 'var(--text1, #e8e8f8)', margin: '12px 0 5px', letterSpacing: '-.02em', lineHeight: 1.3 }}>{children}</h2>,
    h3: ({children}) => <h3 style={{ fontSize: 14.5, fontWeight: 600, color: 'var(--text2, #9090b0)', margin: '10px 0 4px', lineHeight: 1.3 }}>{children}</h3>,
    h4: ({children}) => <h4 style={{ fontSize: 13.5, fontWeight: 600, color: 'var(--text2, #9090b0)', margin: '8px 0 3px' }}>{children}</h4>,
    p: ({children}) => <p style={{ margin: '0 0 8px', color: 'var(--text1, #e8e8f8)', lineHeight: 1.7, fontSize: 14 }}>{children}</p>,
    strong: ({children}) => <strong style={{ color: 'var(--text1, #e8e8f8)', fontWeight: 700 }}>{children}</strong>,
    em: ({children}) => <em style={{ color: 'var(--text3, #555575)' }}>{children}</em>,
    ul: ({children}) => <ul style={{ margin: '6px 0 10px', paddingLeft: 20 }}>{children}</ul>,
    ol: ({children}) => <ol style={{ margin: '6px 0 10px', paddingLeft: 20 }}>{children}</ol>,
    li: ({children}) => <li style={{ margin: '3px 0', color: 'var(--text1, #e8e8f8)', lineHeight: 1.65, fontSize: 14 }}>{children}</li>,
    a: ({href, children}) => <a href={href} target="_blank" rel="noreferrer" style={{ color: '#8b5cf6', textDecoration: 'none', borderBottom: '1px solid rgba(139,92,246,.3)' }}>{children}</a>,
    blockquote: ({children}) => <blockquote style={{ borderLeft: '3px solid #8b5cf6', margin: '8px 0', padding: '4px 12px', color: 'var(--text3, #555575)', background: 'rgba(139,92,246,.05)', borderRadius: '0 6px 6px 0' }}>{children}</blockquote>,
    hr: () => <hr style={{ border: 'none', borderTop: '1px solid var(--border2, #2a2a4a)', margin: '12px 0' }} />,
    table: ({children}) => <div style={{ overflowX: 'auto', margin: '8px 0' }}><table style={{ borderCollapse: 'collapse', fontSize: 13, width: '100%' }}>{children}</table></div>,
    thead: ({children}) => <thead style={{ background: 'var(--bg3, #16162a)' }}>{children}</thead>,
    th: ({children}) => <th style={{ padding: '6px 10px', border: '1px solid var(--border2, #2a2a4a)', textAlign: 'left', color: 'var(--text1, #e8e8f8)', fontWeight: 600 }}>{children}</th>,
    td: ({children}) => <td style={{ padding: '6px 10px', border: '1px solid var(--border2, #2a2a4a)', color: 'var(--text2, #9090b0)' }}>{children}</td>,
    code: ({inline, className, children}) => {
      if (inline) return <code style={{ background: 'rgba(139,92,246,.14)', color: '#c4b5fd', padding: '1px 6px', borderRadius: 5, fontFamily: 'JetBrains Mono, monospace', fontSize: 12.5 }}>{children}</code>;
      const match = /language-(\w+)/.exec(className || '');
      const codeLang = match ? match[1] : '';
      const codeText = String(children).replace(/\n$/, '');
      return <RendererCodeBlock lang={codeLang} codeText={codeText} safeExecuteCodeLocally={safeExecuteCodeLocally} LANG_ENGINE={LANG_ENGINE} ENGINE_META={ENGINE_META} />;
    },
  }), [RendererCodeBlock, safeExecuteCodeLocally, LANG_ENGINE, ENGINE_META]);

  /* ════════════════════════════════════════════════════════════════
   *  RENDER — Codex-style premium UI
   * ════════════════════════════════════════════════════════════════ */
  if (typeof document === 'undefined') return null;
  return createPortal(
    <div data-vortis-code style={{
      position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
      width: '100vw', height: '100vh', height: '100dvh',
      zIndex: 2147483647,
      background: 'radial-gradient(ellipse at top, #0f0f1f 0%, #080812 50%, #050509 100%)',
      color: 'var(--text1, #e8e8f8)',
      display: 'flex', flexDirection: 'column',
      fontFamily: '"Geist Sans", -apple-system, BlinkMacSystemFont, system-ui, sans-serif',
      animation: 'vertexFadeIn .25s cubic-bezier(.4,0,.2,1)',
      overflow: 'hidden',
      isolation: 'isolate',
    }}>
      {/* ═══ Top bar ═══ */}
      <header style={{
        height: 56, flexShrink: 0, display: 'flex', alignItems: 'center', justifyContent: 'space-between',
        padding: '0 18px', borderBottom: '1px solid rgba(139,92,246,.12)',
        background: 'rgba(15,15,31,.7)', backdropFilter: 'blur(20px)', WebkitBackdropFilter: 'blur(20px)',
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 14 }}>
          <button onClick={() => setSidebarOpen(o => !o)} title="Toggle sidebar"
            style={{ background: 'transparent', border: 'none', color: 'var(--text3, #555575)', cursor: 'pointer', padding: 6, borderRadius: 8, display: 'flex', transition: 'all .15s' }}
            onMouseEnter={e => { e.currentTarget.style.background = 'rgba(139,92,246,.1)'; e.currentTarget.style.color = '#c4b5fd'; }}
            onMouseLeave={e => { e.currentTarget.style.background = 'transparent'; e.currentTarget.style.color = 'var(--text3, #555575)'; }}>
            {sidebarOpen ? <PanelLeftClose size={17}/> : <PanelLeftOpen size={17}/>}
          </button>

          {/* Vertex logo + name */}
          <div style={{ display: 'flex', alignItems: 'center', gap: 11 }}>
            <div style={{
              width: 36, height: 36, borderRadius: 11, display: 'flex', alignItems: 'center', justifyContent: 'center',
              background: 'linear-gradient(135deg, rgba(139,92,246,.25), rgba(99,102,241,.15))',
              border: '1px solid rgba(139,92,246,.35)',
              boxShadow: '0 4px 14px rgba(139,92,246,.2), inset 0 1px 0 rgba(255,255,255,.06)',
              position: 'relative',
            }}>
              <VortisLogo size={22} color="#a78bfa"/>
            </div>
            <div>
              <div style={{ display: 'flex', alignItems: 'baseline', gap: 6 }}>
                <span style={{ fontSize: 15.5, fontWeight: 700, color: 'var(--text1, #e8e8f8)', letterSpacing: '-.015em', lineHeight: 1 }}>Vertex</span>
                <span style={{ fontSize: 10, fontWeight: 600, color: '#a78bfa', letterSpacing: '.08em', textTransform: 'uppercase', fontFamily: 'JetBrains Mono' }}>Beta</span>
              </div>
              <div style={{ fontSize: 10.5, color: 'var(--text4, #333355)', marginTop: 3, letterSpacing: '.01em' }}>
                Coding AI by <span style={{ color: '#8b5cf6', fontWeight: 600 }}>Vortis</span>
              </div>
            </div>
          </div>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          {/* GLM-5.2 badge */}
          <div style={{
            display: 'flex', alignItems: 'center', gap: 6, padding: '5px 10px', borderRadius: 7,
            background: 'rgba(139,92,246,.08)', border: '1px solid rgba(139,92,246,.2)',
            fontSize: 11, color: '#c4b5fd', fontFamily: 'JetBrains Mono', fontWeight: 600, letterSpacing: '.03em'
          }} title="Powered by GLM-5.2 via NVIDIA">
            <span style={{ width: 6, height: 6, borderRadius: '50%', background: '#10b981', boxShadow: '0 0 8px #10b981' }}/>
            GLM-5.2
          </div>

          <div style={{ width: 1, height: 20, background: 'rgba(139,92,246,.15)', margin: '0 2px' }} />

          <button onClick={onClose} title="Exit to Vortis (Esc)"
            style={{
              display: 'flex', alignItems: 'center', gap: 6, padding: '6px 12px', borderRadius: 8,
              background: 'rgba(239,68,68,.06)', border: '1px solid rgba(239,68,68,.2)',
              color: '#fca5a5', fontSize: 12.5, fontWeight: 600, cursor: 'pointer', transition: 'all .15s'
            }}
            onMouseEnter={e => { e.currentTarget.style.background = 'rgba(239,68,68,.12)'; e.currentTarget.style.borderColor = 'rgba(239,68,68,.35)'; }}
            onMouseLeave={e => { e.currentTarget.style.background = 'rgba(239,68,68,.06)'; e.currentTarget.style.borderColor = 'rgba(239,68,68,.2)'; }}>
            <X size={13}/> Exit
          </button>
        </div>
      </header>

      {/* ═══ Body: sidebar + main ═══ */}
      <div style={{ flex: 1, display: 'flex', minHeight: 0 }}>
        {/* ── Sidebar ── */}
        {sidebarOpen && (
          <aside style={{
            width: 270, flexShrink: 0,
            borderRight: '1px solid rgba(139,92,246,.1)',
            background: 'rgba(8,8,18,.5)',
            display: 'flex', flexDirection: 'column', minHeight: 0,
            animation: 'vertexSlideIn .2s ease',
          }}>
            {/* New chat */}
            <div style={{ padding: '14px 14px 10px' }}>
              <button onClick={newChat}
                style={{
                  width: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8,
                  padding: '10px 14px', borderRadius: 10, cursor: 'pointer',
                  background: 'linear-gradient(135deg, #8b5cf6, #6366f1)',
                  border: 'none', color: '#fff', fontSize: 13, fontWeight: 600,
                  boxShadow: '0 4px 14px rgba(139,92,246,.35), inset 0 1px 0 rgba(255,255,255,.15)',
                  transition: 'all .15s'
                }}
                onMouseEnter={e => { e.currentTarget.style.transform = 'translateY(-1px)'; e.currentTarget.style.boxShadow = '0 6px 20px rgba(139,92,246,.45), inset 0 1px 0 rgba(255,255,255,.15)'; }}
                onMouseLeave={e => { e.currentTarget.style.transform = 'none'; e.currentTarget.style.boxShadow = '0 4px 14px rgba(139,92,246,.35), inset 0 1px 0 rgba(255,255,255,.15)'; }}>
                <Plus size={15} strokeWidth={2.5}/> New Code Chat
              </button>
            </div>

            {/* Search */}
            <div style={{ padding: '0 14px 10px' }}>
              <div style={{ position: 'relative' }}>
                <Search size={13} style={{ position: 'absolute', left: 11, top: '50%', transform: 'translateY(-50%)', color: 'var(--text4, #333355)' }}/>
                <input
                  value={search} onChange={e => setSearch(e.target.value)} placeholder="Search conversations"
                  style={{
                    width: '100%', padding: '8px 12px 8px 30px', fontSize: 12.5,
                    background: 'rgba(139,92,246,.04)', border: '1px solid rgba(139,92,246,.12)', borderRadius: 8,
                    color: 'var(--text1, #e8e8f8)', outline: 'none', fontFamily: 'inherit',
                    transition: 'all .15s'
                  }}
                  onFocus={e => { e.target.style.borderColor = 'rgba(139,92,246,.35)'; e.target.style.background = 'rgba(139,92,246,.08)'; }}
                  onBlur={e => { e.target.style.borderColor = 'rgba(139,92,246,.12)'; e.target.style.background = 'rgba(139,92,246,.04)'; }}
                />
              </div>
            </div>

            {/* Chat list */}
            <div style={{ flex: 1, overflowY: 'auto', padding: '0 8px' }} className="vertex-scr">
              {filteredChats.length === 0 ? (
                <div style={{ padding: '32px 20px', textAlign: 'center' }}>
                  <div style={{
                    width: 44, height: 44, margin: '0 auto 12px', borderRadius: 12,
                    display: 'flex', alignItems: 'center', justifyContent: 'center',
                    background: 'rgba(139,92,246,.06)', border: '1px solid rgba(139,92,246,.12)'
                  }}>
                    <MessageSquare size={20} style={{ color: 'var(--text4, #333355)' }}/>
                  </div>
                  <div style={{ color: 'var(--text3, #555575)', fontSize: 12.5, fontWeight: 500, marginBottom: 4 }}>
                    {search ? 'No matches found' : 'No conversations yet'}
                  </div>
                  <div style={{ color: 'var(--text4, #333355)', fontSize: 11 }}>
                    {search ? 'Try a different search' : 'Start coding to begin'}
                  </div>
                </div>
              ) : (
                filteredChats.map(c => (
                  <div key={c.id} onClick={() => loadChat(c.id)}
                    style={{
                      padding: '9px 11px', borderRadius: 8, cursor: 'pointer', marginBottom: 2,
                      background: c.id === chatId ? 'rgba(139,92,246,.12)' : 'transparent',
                      border: '1px solid ' + (c.id === chatId ? 'rgba(139,92,246,.25)' : 'transparent'),
                      transition: 'all .12s', position: 'relative'
                    }}
                    onMouseEnter={e => { if (c.id !== chatId) e.currentTarget.style.background = 'rgba(139,92,246,.06)'; }}
                    onMouseLeave={e => { if (c.id !== chatId) e.currentTarget.style.background = 'transparent'; }}>
                    {renamingId === c.id ? (
                      <div style={{ display: 'flex', gap: 4 }} onClick={e => e.stopPropagation()}>
                        <input autoFocus value={renameVal} onChange={e => setRenameVal(e.target.value)}
                          onKeyDown={e => { if (e.key === 'Enter') renameChat(c.id, renameVal); if (e.key === 'Escape') setRenamingId(null); }}
                          style={{ flex: 1, fontSize: 12.5, padding: '3px 6px', background: 'rgba(8,8,18,.9)', border: '1px solid #8b5cf6', borderRadius: 5, color: 'var(--text1, #e8e8f8)', outline: 'none' }}/>
                        <button onClick={() => renameChat(c.id, renameVal)} style={{ background: 'transparent', border: 'none', color: '#10b981', cursor: 'pointer', padding: 2 }}><Check size={12}/></button>
                      </div>
                    ) : (
                      <div style={{ display: 'flex', alignItems: 'flex-start', gap: 8 }}>
                        <div style={{
                          width: 18, height: 18, borderRadius: 5, flexShrink: 0, marginTop: 1,
                          display: 'flex', alignItems: 'center', justifyContent: 'center',
                          background: c.id === chatId ? 'rgba(139,92,246,.2)' : 'rgba(139,92,246,.05)'
                        }}>
                          <Code2 size={10} style={{ color: c.id === chatId ? '#c4b5fd' : 'var(--text4, #333355)' }}/>
                        </div>
                        <div style={{ flex: 1, minWidth: 0 }}>
                          <div style={{
                            fontSize: 12.5, fontWeight: c.id === chatId ? 600 : 500, color: 'var(--text1, #e8e8f8)',
                            whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', lineHeight: 1.3
                          }}>{c.title || 'Untitled'}</div>
                          <div style={{ fontSize: 10, color: 'var(--text4, #333355)', fontFamily: 'JetBrains Mono', marginTop: 2 }}>{relTime(c.updated)}</div>
                        </div>
                        <div className="chat-row-actions" style={{ display: 'flex', gap: 1, opacity: 0, transition: 'opacity .12s' }}
                          onClick={e => e.stopPropagation()}>
                          <button onClick={() => { setRenamingId(c.id); setRenameVal(c.title || ''); }} title="Rename"
                            style={{ background: 'transparent', border: 'none', color: 'var(--text4, #333355)', cursor: 'pointer', padding: 3, borderRadius: 4 }}>
                            <Edit2 size={10}/>
                          </button>
                          <button onClick={() => { if (confirm('Delete this conversation?')) deleteChat(c.id); }} title="Delete"
                            style={{ background: 'transparent', border: 'none', color: 'var(--text4, #333355)', cursor: 'pointer', padding: 3, borderRadius: 4 }}>
                            <Trash2 size={10}/>
                          </button>
                        </div>
                      </div>
                    )}
                  </div>
                ))
              )}
            </div>

            {/* Sidebar footer — user */}
            <div style={{
              padding: '11px 14px', borderTop: '1px solid rgba(139,92,246,.1)',
              background: 'rgba(15,15,31,.4)', display: 'flex', alignItems: 'center', gap: 10
            }}>
              {user?.photoURL ? (
                <img src={user.photoURL} alt="" style={{ width: 28, height: 28, borderRadius: '50%', border: '1px solid rgba(139,92,246,.3)' }}/>
              ) : (
                <div style={{
                  width: 28, height: 28, borderRadius: '50%',
                  background: 'linear-gradient(135deg, #8b5cf6, #6366f1)',
                  display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#fff', fontSize: 11, fontWeight: 700,
                  border: '1px solid rgba(139,92,246,.3)'
                }}>
                  {(user?.displayName || user?.email || '?')[0].toUpperCase()}
                </div>
              )}
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 12, fontWeight: 600, color: 'var(--text1, #e8e8f8)', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                  {user?.displayName || 'User'}
                </div>
                <div style={{ fontSize: 10, color: 'var(--text4, #333355)', fontFamily: 'JetBrains Mono' }}>
                  {savedChats.length} {savedChats.length === 1 ? 'conversation' : 'conversations'}
                </div>
              </div>
            </div>
          </aside>
        )}

        {/* ── Main chat area ── */}
        <main style={{ flex: 1, display: 'flex', flexDirection: 'column', minWidth: 0, position: 'relative' }}>
          {/* Subtle background gradient */}
          <div style={{
            position: 'absolute', inset: 0, pointerEvents: 'none',
            background: 'radial-gradient(circle at 30% 0%, rgba(139,92,246,.06), transparent 50%), radial-gradient(circle at 70% 100%, rgba(99,102,241,.04), transparent 50%)'
          }}/>

          {/* Messages / empty state */}
          <div ref={scrollRef} style={{ flex: 1, overflowY: 'auto', position: 'relative' }} className="vertex-scr">
            {messages.length === 0 && !streaming ? (
              /* ── Codex-style empty state ── */
              <div style={{
                height: '100%', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center',
                padding: '40px 24px', textAlign: 'center', position: 'relative'
              }}>
                {/* Glowing logo orb */}
                <div style={{
                  width: 76, height: 76, borderRadius: 22, marginBottom: 24,
                  display: 'flex', alignItems: 'center', justifyContent: 'center',
                  background: 'linear-gradient(135deg, rgba(139,92,246,.25), rgba(99,102,241,.15))',
                  border: '1px solid rgba(139,92,246,.4)',
                  boxShadow: '0 0 60px rgba(139,92,246,.25), 0 12px 30px rgba(0,0,0,.4), inset 0 1px 0 rgba(255,255,255,.08)',
                  position: 'relative', animation: 'vertexFloat 3s ease-in-out infinite'
                }}>
                  <VortisLogo size={44} color="#c4b5fd"/>
                  <div style={{
                    position: 'absolute', inset: -8, borderRadius: 28, pointerEvents: 'none',
                    background: 'radial-gradient(circle, rgba(139,92,246,.15), transparent 70%)',
                    animation: 'vertexGlow 3s ease-in-out infinite'
                  }}/>
                </div>

                <h1 style={{
                  fontSize: 30, fontWeight: 700, color: 'var(--text1, #e8e8f8)', margin: '0 0 8px',
                  letterSpacing: '-.025em', lineHeight: 1.1,
                  background: 'linear-gradient(135deg, #fff 0%, #c4b5fd 100%)',
                  WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent', backgroundClip: 'text'
                }}>
                  What should we build?
                </h1>
                <p style={{
                  fontSize: 14, color: 'var(--text3, #555575)', maxWidth: 460, lineHeight: 1.6, margin: '0 0 32px'
                }}>
                  I'm <span style={{ color: '#c4b5fd', fontWeight: 600 }}>Vertex</span> — your coding AI by Vortis. Debug, refactor, ship features, or learn a new pattern. Powered by GLM-5.2.
                </p>

                {/* Starter prompts — premium cards */}
                <div style={{
                  display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(220px, 1fr))',
                  gap: 10, maxWidth: 720, width: '100%'
                }}>
                  {STARTER_PROMPTS.map(s => {
                    const Icon = ICONS[s.icon] || FileCode;
                    return (
                      <button key={s.label}
                        onClick={() => { setInput(s.prompt); setTimeout(() => inputRef.current?.focus(), 30); }}
                        style={{
                          textAlign: 'left', padding: '13px 15px', borderRadius: 12, cursor: 'pointer',
                          background: 'rgba(139,92,246,.04)', border: '1px solid rgba(139,92,246,.12)',
                          color: 'var(--text1, #e8e8f8)', display: 'flex', flexDirection: 'column', gap: 6,
                          transition: 'all .18s cubic-bezier(.4,0,.2,1)', position: 'relative', overflow: 'hidden'
                        }}
                        onMouseEnter={e => {
                          e.currentTarget.style.background = 'rgba(139,92,246,.1)';
                          e.currentTarget.style.borderColor = 'rgba(139,92,246,.35)';
                          e.currentTarget.style.transform = 'translateY(-2px)';
                          e.currentTarget.style.boxShadow = '0 8px 24px rgba(139,92,246,.15)';
                        }}
                        onMouseLeave={e => {
                          e.currentTarget.style.background = 'rgba(139,92,246,.04)';
                          e.currentTarget.style.borderColor = 'rgba(139,92,246,.12)';
                          e.currentTarget.style.transform = 'none';
                          e.currentTarget.style.boxShadow = 'none';
                        }}>
                        <div style={{
                          width: 28, height: 28, borderRadius: 8, marginBottom: 2,
                          display: 'flex', alignItems: 'center', justifyContent: 'center',
                          background: 'linear-gradient(135deg, rgba(139,92,246,.2), rgba(99,102,241,.1))',
                          border: '1px solid rgba(139,92,246,.2)'
                        }}>
                          <Icon size={14} color="#c4b5fd"/>
                        </div>
                        <span style={{ fontSize: 13, fontWeight: 600, color: 'var(--text1, #e8e8f8)' }}>{s.label}</span>
                        <span style={{ fontSize: 11, color: 'var(--text4, #333355)', lineHeight: 1.4 }}>{s.desc}</span>
                      </button>
                    );
                  })}
                </div>

                <div style={{
                  marginTop: 32, display: 'flex', alignItems: 'center', gap: 16,
                  fontSize: 10.5, color: 'var(--text4, #333355)', fontFamily: 'JetBrains Mono', letterSpacing: '.04em'
                }}>
                  <span><kbd style={kbdStyle}>⌘/Ctrl</kbd> + <kbd style={kbdStyle}>Enter</kbd> send</span>
                  <span style={{ color: 'rgba(139,92,246,.2)' }}>•</span>
                  <span><kbd style={kbdStyle}>⌘/Ctrl</kbd> + <kbd style={kbdStyle}>K</kbd> new chat</span>
                  <span style={{ color: 'rgba(139,92,246,.2)' }}>•</span>
                  <span><kbd style={kbdStyle}>Esc</kbd> exit</span>
                </div>
              </div>
            ) : (
              /* ── Messages list ── */
              <div style={{ maxWidth: 820, margin: '0 auto', padding: '24px 24px 12px', position: 'relative' }}>
                {messages.map(m => (
                  <MessageBubble key={m.id} role={m.role} text={m.text} ts={m.ts} mdComponents={mdComponents} />
                ))}

                {/* Streaming bubble */}
                {(streaming || thinking) && (
                  <div style={{ display: 'flex', gap: 12, marginBottom: 16 }}>
                    <div style={{
                      width: 32, height: 32, borderRadius: 9, flexShrink: 0, display: 'flex', alignItems: 'center', justifyContent: 'center',
                      background: 'linear-gradient(135deg, rgba(139,92,246,.25), rgba(99,102,241,.15))',
                      border: '1px solid rgba(139,92,246,.35)',
                      boxShadow: '0 0 20px rgba(139,92,246,.15)'
                    }}>
                      <VortisLogo size={18} color="#c4b5fd"/>
                    </div>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ fontSize: 11, color: 'var(--text4, #333355)', fontFamily: 'JetBrains Mono', marginBottom: 6, fontWeight: 600, letterSpacing: '.04em' }}>
                        VERTEX {thinking && <span style={{ color: '#a78bfa' }}>· thinking</span>}
                      </div>
                      {thinking ? (
                        <div style={{ display: 'flex', gap: 5, padding: '6px 0' }}>
                          {[0,1,2].map(i => (
                            <div key={i} style={{
                              width: 7, height: 7, borderRadius: '50%', background: '#8b5cf6',
                              animation: `vertexPulse 1.2s ease-in-out ${i*0.15}s infinite`
                            }}/>
                          ))}
                        </div>
                      ) : streamText ? (
                        <div style={{
                          background: 'rgba(139,92,246,.04)', border: '1px solid rgba(139,92,246,.12)',
                          borderRadius: '4px 14px 14px 14px', padding: '13px 16px'
                        }}>
                          <ReactMarkdown remarkPlugins={[remarkGfm, remarkMath]} rehypePlugins={[rehypeKatex]} components={mdComponents}>
                            {streamText}
                          </ReactMarkdown>
                          <span style={{ display: 'inline-block', width: 8, height: 15, background: '#a78bfa', marginLeft: 2, verticalAlign: 'text-bottom', animation: 'vertexBlink 1s steps(2) infinite', borderRadius: 1 }}/>
                        </div>
                      ) : null}
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>

          {/* ── Input area ── */}
          <div style={{
            flexShrink: 0, borderTop: '1px solid rgba(139,92,246,.1)',
            background: 'rgba(15,15,31,.6)', backdropFilter: 'blur(20px)', WebkitBackdropFilter: 'blur(20px)',
            padding: '14px 24px 18px'
          }}>
            <div style={{ maxWidth: 820, margin: '0 auto' }}>
              <div style={{
                position: 'relative', background: 'rgba(8,8,18,.7)',
                border: '1px solid rgba(139,92,246,.2)', borderRadius: 14,
                transition: 'all .2s', boxShadow: '0 4px 24px rgba(0,0,0,.3)'
              }}>
                <textarea
                  ref={inputRef}
                  value={input}
                  onChange={e => setInput(e.target.value)}
                  onKeyDown={e => { if ((e.metaKey || e.ctrlKey) && e.key === 'Enter') { e.preventDefault(); send(); } }}
                  placeholder="Ask Vertex anything about code…"
                  rows={1}
                  style={{
                    width: '100%', minHeight: 54, maxHeight: 240, resize: 'none',
                    padding: '14px 60px 14px 16px', background: 'transparent', border: 'none', outline: 'none',
                    color: 'var(--text1, #e8e8f8)', fontSize: 14, lineHeight: 1.55, fontFamily: 'inherit',
                    boxSizing: 'border-box'
                  }}
                  onFocus={e => { e.target.parentElement.style.borderColor = 'rgba(139,92,246,.45)'; e.target.parentElement.style.boxShadow = '0 4px 24px rgba(0,0,0,.3), 0 0 0 3px rgba(139,92,246,.08)'; }}
                  onBlur={e => { e.target.parentElement.style.borderColor = 'rgba(139,92,246,.2)'; e.target.parentElement.style.boxShadow = '0 4px 24px rgba(0,0,0,.3)'; }}
                />
                <div style={{ position: 'absolute', right: 9, bottom: 9, display: 'flex', gap: 4 }}>
                  {streaming ? (
                    <button onClick={stopStreaming} title="Stop"
                      style={{
                        width: 36, height: 36, borderRadius: 9, border: 'none', cursor: 'pointer',
                        background: 'rgba(239,68,68,.15)', border: '1px solid rgba(239,68,68,.3)',
                        color: '#fca5a5', display: 'flex', alignItems: 'center', justifyContent: 'center'
                      }}>
                      <Loader size={15} style={{ animation: 'vertexSpin 1s linear infinite' }}/>
                    </button>
                  ) : (
                    <button onClick={() => send()} disabled={!input.trim()}
                      title="Send (⌘/Ctrl + Enter)"
                      style={{
                        width: 36, height: 36, borderRadius: 9, border: 'none',
                        cursor: input.trim() ? 'pointer' : 'not-allowed',
                        background: input.trim() ? 'linear-gradient(135deg, #8b5cf6, #6366f1)' : 'rgba(139,92,246,.1)',
                        color: '#fff', display: 'flex', alignItems: 'center', justifyContent: 'center',
                        opacity: input.trim() ? 1 : 0.4, transition: 'all .2s',
                        boxShadow: input.trim() ? '0 4px 12px rgba(139,92,246,.4)' : 'none'
                      }}>
                      <ArrowUp size={16} strokeWidth={2.5}/>
                    </button>
                  )}
                </div>
              </div>
              <div style={{
                display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                marginTop: 9, fontSize: 10.5, color: 'var(--text4, #333355)', fontFamily: 'JetBrains Mono'
              }}>
                <span>Vertex · GLM-5.2 · by Vortis</span>
                <span>{input.length} chars</span>
              </div>
            </div>
          </div>
        </main>
      </div>

      {/* Inline styles — keyframes + scoped reset */}
      <style>{`
        @keyframes vertexFadeIn { from { opacity: 0 } to { opacity: 1 } }
        @keyframes vertexSlideIn { from { transform: translateX(-100%); opacity: 0 } to { transform: translateX(0); opacity: 1 } }
        @keyframes vertexFloat { 0%, 100% { transform: translateY(0) } 50% { transform: translateY(-6px) } }
        @keyframes vertexGlow { 0%, 100% { opacity: .5 } 50% { opacity: 1 } }
        @keyframes vertexPulse { 0%, 100% { opacity: .3; transform: scale(.85) } 50% { opacity: 1; transform: scale(1) } }
        @keyframes vertexBlink { 50% { opacity: 0 } }
        @keyframes vertexSpin { from { transform: rotate(0deg) } to { transform: rotate(360deg) } }

        /* Scoped reset — immune to global stylesheets */
        [data-vortis-code], [data-vortis-code] *, [data-vortis-code] *::before, [data-vortis-code] *::after {
          box-sizing: border-box; margin: 0; padding: 0; border: 0;
          font: inherit; font-size: inherit; color: inherit; background: transparent;
          list-style: none; text-decoration: none; vertical-align: baseline;
        }
        [data-vortis-code] button { cursor: pointer; background: transparent; border: none; color: inherit; font: inherit; }
        [data-vortis-code] input, [data-vortis-code] textarea, [data-vortis-code] select {
          font: inherit; color: inherit; background: transparent; border: none; outline: none;
        }
        [data-vortis-code] img { max-width: 100%; display: block; }
        [data-vortis-code] kbd {
          display: inline-block; padding: 1px 5px; font-size: 10px; font-family: 'JetBrains Mono', monospace;
          background: rgba(139,92,246,.1); border: 1px solid rgba(139,92,246,.2); border-radius: 4px;
          color: #c4b5fd; font-weight: 600;
        }

        /* Custom scrollbar */
        [data-vortis-code] .vertex-scr::-webkit-scrollbar { width: 8px; }
        [data-vortis-code] .vertex-scr::-webkit-scrollbar-track { background: transparent; }
        [data-vortis-code] .vertex-scr::-webkit-scrollbar-thumb {
          background: rgba(139,92,246,.2); border-radius: 4px;
        }
        [data-vortis-code] .vertex-scr::-webkit-scrollbar-thumb:hover { background: rgba(139,92,246,.35); }

        /* Show chat row actions on hover */
        [data-vortis-code] div:hover > div > .chat-row-actions { opacity: 1 !important; }
      `}</style>
    </div>,
    document.body
  );
};

/* ═══════════════════════════════════════════════════════════════════
 *  Single message bubble
 * ═══════════════════════════════════════════════════════════════════ */
const MessageBubble = React.memo(({ role, text, ts, mdComponents }) => {
  const isUser = role === 'user';
  const [copied, setCopied] = useState(false);
  const copy = () => { navigator.clipboard.writeText(text); setCopied(true); setTimeout(() => setCopied(false), 1500); };

  if (isUser) {
    return (
      <div style={{ display: 'flex', gap: 12, marginBottom: 20, justifyContent: 'flex-end' }}>
        <div style={{
          maxWidth: '78%',
          background: 'linear-gradient(135deg, #8b5cf6, #6366f1)',
          color: '#fff', borderRadius: '16px 16px 4px 16px', padding: '11px 16px',
          fontSize: 14, lineHeight: 1.55, whiteSpace: 'pre-wrap', wordBreak: 'break-word',
          boxShadow: '0 4px 14px rgba(139,92,246,.25)'
        }}>
          {text}
        </div>
      </div>
    );
  }

  return (
    <div style={{ display: 'flex', gap: 12, marginBottom: 20 }}>
      <div style={{
        width: 32, height: 32, borderRadius: 9, flexShrink: 0, display: 'flex', alignItems: 'center', justifyContent: 'center',
        background: 'linear-gradient(135deg, rgba(139,92,246,.25), rgba(99,102,241,.15))',
        border: '1px solid rgba(139,92,246,.35)',
        boxShadow: '0 0 20px rgba(139,92,246,.1)'
      }}>
        <VortisLogo size={18} color="#c4b5fd"/>
      </div>
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{
          display: 'flex', alignItems: 'center', gap: 8, marginBottom: 6,
          fontSize: 11, color: 'var(--text4, #333355)', fontFamily: 'JetBrains Mono', fontWeight: 600, letterSpacing: '.04em'
        }}>
          VERTEX
          {ts && <span style={{ color: 'var(--text4, #333355)', opacity: .7, fontWeight: 400 }}>· {new Date(ts).toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' })}</span>}
          <button onClick={copy} title="Copy response"
            style={{ marginLeft: 'auto', background: 'transparent', border: 'none', color: copied ? '#10b981' : 'var(--text4, #333355)', cursor: 'pointer', padding: 2, borderRadius: 4, display: 'flex', alignItems: 'center', gap: 3, fontSize: 10.5, transition: 'color .15s' }}>
            {copied ? <Check size={11}/> : <Copy size={11}/>} {copied ? 'Copied' : ''}
          </button>
        </div>
        <div style={{
          background: 'rgba(139,92,246,.04)', border: '1px solid rgba(139,92,246,.12)',
          borderRadius: '4px 14px 14px 14px', padding: '13px 16px'
        }}>
          <ReactMarkdown remarkPlugins={[remarkGfm, remarkMath]} rehypePlugins={[rehypeKatex]} components={mdComponents}>
            {text}
          </ReactMarkdown>
        </div>
      </div>
    </div>
  );
});

export default CodeChat;
